 const hip=fkr.P['hip'+s],tb=twoBone(hip,foot.o,B.th,B.sk,pole||M3.col(foot.R,2));
 const P=fkr.F.pelvis.R,a=V.unit(V.sub(tb.mid,hip)),sd=V.unit(V.sub(tb.end,tb.mid));
 let zf=V.scale(V.perp(sd,a),-1);
