 for(let i=1;i<prof.length;i++)if(t<=prof[i][0]){const a=prof[i-1],b=prof[i],u=(t-a[0])/(b[0]-a[0]);return a.slice(1).map((v,k)=>lerp(v,b[k+1],u));}
