/* Точка поверхности корпуса: side — 'L'/'R', ang ∈ [0, π] от передней линии через бок к спине */
function torsoPoint(R,h,side,ang,extra=0){return torsoPointIn(R,h,side,ang,extra,torsoFrame(R,h),sectionAt(h));}
