 const u=V.dot(V.sub(p,lo),ab)/(L*L),t=clamp(u,0,1),c=V.mix(lo,hi,t),z=V.unit(V.mix(n.z,h.z,t)),x=V.unit(V.mix(n.x,h.x,t)),[rf,rb,rl]=profileAt(NECK,t);
