function limbRow(R,kind,side,t){const[,a,b]=LIMB_DEF[kind],center=V.mix(R[a+side],R[b+side],t),ax=limbAxes(R,kind,side,t),prof=profileAt(LIMBS[kind],t);return(ang,extra=0)=>limbPointIn(center,ax,prof,ang,extra);}
