  if(g&&q.kf>0){const kf=q.kf,gc=g.c,gz=g.z,gx=g.x,r0=gc[0]+gz[0]*dz+gx[0]*dx,r1=gc[1]+gz[1]*dz+gx[1]*dx,r2=gc[2]+gz[2]*dz+gx[2]*dx;p=[p[0]+(r0-p[0])*kf,p[1]+(r1-p[1])*kf,p[2]+(r2-p[2])*kf];}
