 const{ys,cols}=HEAD_ROWS_K;let i=0;while(i<ys.length-2&&y>ys[i+1])i++;
 const h=ys[i+1]-ys[i],t=(y-ys[i])/h,t2=t*t,t3=t2*t;
 return cols.map(c=>(2*t3-3*t2+1)*c.v[i]+(t3-2*t2+t)*h*c.m[i]+(-2*t3+3*t2)*c.v[i+1]+(t3-t2)*h*c.m[i+1]);
