const headLocal=(R,p)=>{const d=V.sub(p,R.head),f=R.frames.head;return[V.dot(d,f.x),V.dot(d,f.y),V.dot(d,f.z)];};
const headWorld=(R,l)=>{const f=R.frames.head;return V.add(V.add(V.add(R.head,f.x,l[0]),f.y,l[1]),f.z,l[2]);};
