 const out=[];
 for(let j=1;j<17;j++)for(let i=0;i<24;i++){const th=j/17*Math.PI,ph=i/24*2*Math.PI,u=[Math.sin(th)*Math.sin(ph),Math.cos(th),Math.sin(th)*Math.cos(ph)];out.push(V.scale(u,headRay(u)));}
