 for(const t of [[0,-3,11.7],[-.8,-3.6,10.9],[.8,-3.6,10.9],[0,-9.3,9],[0,-11.3,5.5],[0,2.2,9.4]]){const u=V.unit(t);out.push(V.scale(u,headRay(u)));}
