 const out=st.parts.map(p=>({...p}));
 for(const e of list)if(BIND[e.type])for(const p of BIND[e.type](e,R)){p.dyn=true;if(e.optional)p.optional=e.optional;if(e.optionalNot)p.optionalNot=e.optionalNot;out.push(p);}
