      for (let r = 0; r < 3; r++) { out[i * 12 + r * 4] = A.lin[r][0]; out[i * 12 + r * 4 + 1] = A.lin[r][1]; out[i * 12 + r * 4 + 2] = A.lin[r][2]; out[i * 12 + r * 4 + 3] = A.t[r]; }
