    if (window.GymVolume && step.view !== 'mannequin') await perfUntil(() => root()?.dataset.anatomy === 'on' || root()?.dataset.renderer !== 'webgl', 10000, run);
    out.wait = performance.now() - t0 - out.open; out.view = perfViewOf(root());
